package org.apache.commons.lang3;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.ObjectStreamClass;
import java.io.ObjectStreamException;
import java.io.OutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClassLoaderAwareObjectInputStream_ClassLoaderAwareObjectInputStream_TriageGen0Test {

    @Test
    public void testConstructorSuccess() throws IOException {
        InputStream in = new ByteArrayInputStream(new byte[0]);
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

        SerializationUtils.ClassLoaderAwareObjectInputStream stream = 
            new SerializationUtils.ClassLoaderAwareObjectInputStream(in, classLoader);

        assertNotNull(stream);
    }

    @Test(expected = IOException.class)
    public void testConstructorThrowsIOException() throws IOException {
        InputStream in = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated IO failure");
            }
        };
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

        // The constructor calls super(in), which might trigger logic in ObjectInputStream
        // However, to force an IOException during construction in standard Java, 
        // we rely on the stream behavior if the superclass constructor validates the stream.
        new SerializationUtils.ClassLoaderAwareObjectInputStream(in, classLoader);
    }

    @Test
    public void testResolveClassWithMock() throws Exception {
        // This tests the protected method resolveClass via a subclass or direct test if possible
        // Since it's protected, we use a test subclass to expose it for coverage
        InputStream in = new ByteArrayInputStream(new byte[0]);
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

        TestClassLoaderAwareObjectInputStream stream = new TestClassLoaderAwareObjectInputStream(in, classLoader);
        ObjectStreamClass mockDesc = mock(ObjectStreamClass.class);

        // We don't necessarily need to call resolveClass here to test the constructor,
        // but to ensure the class structure is covered:
        stream.resolveClass(mockDesc);
    }

    /**
     * Subclass to allow testing of the protected resolveClass method
     */
    private static class TestClassLoaderAwareObjectInputStream extends SerializationUtils.ClassLoaderAwareObjectInputStream {
        public TestClassLoaderAwareObjectInputStream(InputStream in, ClassLoader classLoader) throws IOException {
            super(in, classLoader);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            return super.resolveClass(desc);
        }
    }
}
